import React, { useReducer, useEffect, useMemo } from 'react';
import './Jubilacion.css';
import { LineChart, Line, XAxis, YAxis, CartesianGrid, Tooltip, Legend, ResponsiveContainer } from 'recharts';
import { addDays, format } from 'date-fns';

// Obtener la URL base de la API desde variables de entorno
const API_BASE_URL = process.env.REACT_APP_API_BASE_URL;

// Estado inicial y reducer para la gestión del estado
const initialState = {
    prophetData: [],
    armaData: [],
    loadingProphet: true,
    loadingArma: true,
    errorProphet: null,
    errorArma: null,
    showProphetPrediction: false,
    showArmaPrediction: false
};

const reducer = (state, action) => {
    switch (action.type) {
        case 'FETCH_PROPHET_SUCCESS':
            return { ...state, prophetData: action.payload, loadingProphet: false };
        case 'FETCH_PROPHET_ERROR':
            return { ...state, errorProphet: action.payload, loadingProphet: false };
        case 'FETCH_ARMA_SUCCESS':
            return { ...state, armaData: action.payload, loadingArma: false };
        case 'FETCH_ARMA_ERROR':
            return { ...state, errorArma: action.payload, loadingArma: false };
        case 'TOGGLE_PROPHET_PREDICTION':
            return { ...state, showProphetPrediction: !state.showProphetPrediction };
        case 'TOGGLE_ARMA_PREDICTION':
            return { ...state, showArmaPrediction: !state.showArmaPrediction };
        default:
            return state;
    }
};

const Jubilacion = () => {
    const [state, dispatch] = useReducer(reducer, initialState);

    // Función para obtener los datos y predicciones de Prophet del backend
    const fetchProphetData = async () => {
        try {
            const response = await fetch(`${API_BASE_URL}/prophet-predictions`);
            if (!response.ok) {
                // Intenta leer el cuerpo de la respuesta para obtener detalles del error
                const errorText = await response.text();
                throw new Error(`Error: ${response.status} ${response.statusText} - ${errorText}`);
            }

            // Verificar el tipo de contenido
            const contentType = response.headers.get('content-type');
            if (!contentType || !contentType.includes('application/json')) {
                throw new Error('El servidor no devolvió un JSON válido');
            }

            const result = await response.json();

            // Formatear los datos reales de Prophet
            const chartData = result.dates.map((date, index) => ({
                date: date,
                valueProphet: result.values[index] || null,       // Valor real de Prophet
                predictionProphet: null  // No hay predicción para estas fechas
            }));

            // Crear un arreglo de predicciones de Prophet
            const lastDateProphet = new Date(chartData[chartData.length - 1].date);
            const predictionsDataProphet = result.predictions.map((prediction, index) => {
                const newDate = addDays(lastDateProphet, index + 1);
                return {
                    date: format(newDate, 'yyyy-MM-dd'), // Formato YYYY-MM-DD
                    valueProphet: null, // No hay valor real para los días de predicción
                    predictionProphet: prediction // Predicciones de Prophet
                };
            });

            // Combinar datos reales y predicciones de Prophet
            const combinedProphetData = [...chartData, ...predictionsDataProphet];
            dispatch({ type: 'FETCH_PROPHET_SUCCESS', payload: combinedProphetData });
        } catch (error) {
            console.error('Error fetching Prophet data:', error);
            dispatch({ type: 'FETCH_PROPHET_ERROR', payload: error.message });
        }
    };

    // Función para obtener los datos y predicciones de ARMA del backend
    const fetchArmaData = async () => {
        try {
            const response = await fetch(`${API_BASE_URL}/arma-predictions`);
            if (!response.ok) {
                // Intenta leer el cuerpo de la respuesta para obtener detalles del error
                const errorText = await response.text();
                throw new Error(`Error: ${response.status} ${response.statusText} - ${errorText}`);
            }

            // Verificar el tipo de contenido
            const contentType = response.headers.get('content-type');
            if (!contentType || !contentType.includes('application/json')) {
                throw new Error('El servidor no devolvió un JSON válido');
            }

            const result = await response.json();

            // Formatear los datos reales de ARMA
            const chartData = result.dates.map((date, index) => ({
                date: date,
                valueArma: result.values[index] || null,       // Valor real de ARMA
                predictionArma: null  // No hay predicción para estas fechas
            }));

            // Crear un arreglo de predicciones de ARMA
            const lastDateArma = new Date(chartData[chartData.length - 1].date);
            const predictionsDataArma = result.predictions.map((prediction, index) => {
                const newDate = addDays(lastDateArma, index + 1);
                return {
                    date: format(newDate, 'yyyy-MM-dd'), // Formato YYYY-MM-DD
                    valueArma: null, // No hay valor real para los días de predicción
                    predictionArma: prediction // Predicciones de ARMA
                };
            });

            // Combinar datos reales y predicciones de ARMA
            const combinedArmaData = [...chartData, ...predictionsDataArma];
            dispatch({ type: 'FETCH_ARMA_SUCCESS', payload: combinedArmaData });
        } catch (error) {
            console.error('Error fetching ARMA data:', error);
            dispatch({ type: 'FETCH_ARMA_ERROR', payload: error.message });
        }
    };

    useEffect(() => {
        // Llamar a ambas funciones de fetch cuando el componente se monte
        fetchProphetData();
        fetchArmaData();
    }, []);

    // Función para alternar la visibilidad de las predicciones Prophet
    const toggleProphetPrediction = () => {
        dispatch({ type: 'TOGGLE_PROPHET_PREDICTION' });
    };

    // Función para alternar la visibilidad de las predicciones ARMA
    const toggleArmaPrediction = () => {
        dispatch({ type: 'TOGGLE_ARMA_PREDICTION' });
    };

    // Combinar datos de Prophet y ARMA para el gráfico
    const mergedData = useMemo(() => {
        const combined = {};

        // Agregar datos de Prophet
        state.prophetData.forEach(item => {
            if (!combined[item.date]) {
                combined[item.date] = { date: item.date };
            }
            combined[item.date].valueProphet = item.valueProphet;
            combined[item.date].predictionProphet = item.predictionProphet;
        });

        // Agregar datos de ARMA
        state.armaData.forEach(item => {
            if (!combined[item.date]) {
                combined[item.date] = { date: item.date };
            }
            combined[item.date].valueArma = item.valueArma;
            combined[item.date].predictionArma = item.predictionArma;
        });

        // Convertir el objeto combinado a un arreglo ordenado por fecha
        const sortedDates = Object.keys(combined).sort((a, b) => new Date(a) - new Date(b));
        return sortedDates.map(date => combined[date]);
    }, [state.prophetData, state.armaData]);

    return (
        <div className="jubilacion-container">
            <h1 className="jubilacion-title">Predicción de Moneda usando Prophet y ARMA</h1>
            <div className="jubilacion-content">
                <p>
                    Este gráfico muestra el precio del dólar frente al peso mexicano (MXN) y las predicciones de los modelos
                    Prophet y ARMA.
                </p>

                {(state.loadingProphet || state.loadingArma) ? (
                    <p>Cargando datos...</p>
                ) : (state.errorProphet || state.errorArma) ? (
                    <p>Error al cargar datos: {state.errorProphet || state.errorArma}</p>
                ) : (
                    <>
                        <div className="buttons-container">
                            <button onClick={toggleProphetPrediction}>
                                {state.showProphetPrediction ? 'Ocultar Predicción Prophet' : 'Mostrar Predicción Prophet'}
                            </button>
                            <button onClick={toggleArmaPrediction}>
                                {state.showArmaPrediction ? 'Ocultar Predicción ARMA' : 'Mostrar Predicción ARMA'}
                            </button>
                        </div>
                        <ResponsiveContainer width="100%" height={500}>
                            <LineChart data={mergedData}>
                                <CartesianGrid strokeDasharray="3 3" />
                                <XAxis dataKey="date" />
                                <YAxis />
                                <Tooltip />
                                <Legend />
                                {/* Línea para los datos reales de Prophet */}
                                <Line
                                    type="monotone"
                                    dataKey="valueProphet"
                                    stroke="#007bff"
                                    name="Valor Real Prophet"
                                    dot={false}
                                />
                                {/* Línea para las predicciones de Prophet */}
                                {state.showProphetPrediction && (
                                    <Line
                                        type="monotone"
                                        dataKey="predictionProphet"
                                        stroke="#00ff00"
                                        name="Predicción Prophet"
                                        dot={false}
                                        strokeDasharray="5 5"
                                    />
                                )}
                                {/* Línea para los datos reales de ARMA */}
                                <Line
                                    type="monotone"
                                    dataKey="valueArma"
                                    stroke="#ff0000"
                                    name="Valor Real ARMA"
                                    dot={false}
                                />
                                {/* Línea para las predicciones de ARMA */}
                                {state.showArmaPrediction && (
                                    <Line
                                        type="monotone"
                                        dataKey="predictionArma"
                                        stroke="#ff9900"
                                        name="Predicción ARMA"
                                        dot={false}
                                        strokeDasharray="5 5"
                                    />
                                )}
                            </LineChart>
                        </ResponsiveContainer>
                    </>
                )}
            </div>
        </div>
    );
};

export default Jubilacion;
